using System; using System.Drawing; using System.Windows.Forms; using AshkanLMS.Core; using AshkanLMS.Services;
namespace AshkanLMS.UI { public class LoginForm:Form { TextBox user=new TextBox(),pass=new TextBox(); Label error; readonly DataService data=new DataService(); Panel left,card; Button language; public LoginForm(){StartPosition=FormStartPosition.CenterScreen;Size=new Size(1000,620);MinimumSize=new Size(900,560);BackColor=Color.FromArgb(224,234,248);BackgroundImage=Theme.LoadBackgroundImage();BackgroundImageLayout=ImageLayout.Zoom;Font=Theme.Font();FormBorderStyle=FormBorderStyle.FixedSingle;MaximizeBox=false;Build();if(!string.IsNullOrEmpty(data.FirstRunMessage))MessageBox.Show(data.FirstRunMessage,"Initial administrator account",MessageBoxButtons.OK,MessageBoxIcon.Information);}
void Build(){Controls.Clear();Localization.Direction(this);Text="AshkanLMS • "+Localization.T("LoginTitle"); left=new Panel{Dock=AppSession.Persian?DockStyle.Right:DockStyle.Left,Width=430,BackColor=Color.FromArgb(235,22,34,53)};Controls.Add(left);var brand=new Label{Text="A",ForeColor=Color.White,BackColor=Theme.Blue,TextAlign=ContentAlignment.MiddleCenter,Font=Theme.Font(28,FontStyle.Bold),Size=new Size(68,68),Location=new Point(48,70)};left.Controls.Add(brand);var t=new Label{Text="AshkanLMS",ForeColor=Color.White,Font=Theme.Font(25,FontStyle.Bold),AutoSize=true,Location=new Point(48,160),RightToLeft=RightToLeft.No};left.Controls.Add(t);var d=new Label{Text=Localization.T("BrandText"),ForeColor=Color.FromArgb(196,207,224),Font=Theme.Font(11),AutoSize=true,Location=new Point(50,215)};left.Controls.Add(d);var badge=new Label{Text="  "+Localization.T("Secure")+"  ",ForeColor=Color.White,BackColor=Color.FromArgb(36,52,76),Font=Theme.Font(9,FontStyle.Bold),AutoSize=true,Padding=new Padding(7),Location=new Point(50,360)};left.Controls.Add(badge);
card=new ModernCard{BackColor=Theme.Card,Size=new Size(420,450),Location=AppSession.Persian?new Point(80,70):new Point(500,70),Padding=new Padding(36)};Controls.Add(card);var h=Theme.Label(Localization.T("Welcome"),22,FontStyle.Bold);h.Location=new Point(35,35);card.Controls.Add(h);var sub=Theme.Label(Localization.T("LoginSub"),9);sub.ForeColor=Theme.Muted;sub.Location=new Point(37,80);card.Controls.Add(sub);AddField(card,Localization.T("Username"),user,125);AddField(card,Localization.T("Password"),pass,205);pass.UseSystemPasswordChar=true;var b=Theme.Button(Localization.T("SignIn"));b.Location=new Point(36,300);b.Width=348;b.Click+=(s,e)=>DoLogin();card.Controls.Add(b);error=Theme.Label("",9,FontStyle.Bold);error.ForeColor=Theme.Red;error.Location=new Point(36,350);card.Controls.Add(error);var hint=Theme.Label("First run: credentials in LocalAppData/AshkanLMS",8);hint.ForeColor=Theme.Muted;hint.Location=new Point(36,385);hint.RightToLeft=RightToLeft.No;card.Controls.Add(hint);language=Theme.Button(Localization.T("Language"));language.Location=new Point(278,10);language.Size=new Size(106,32);language.Click+=(s,e)=>{var u=user.Text;var pw=pass.Text;Localization.Set(!AppSession.Persian);Build();user.Text=u;pass.Text=pw;};card.Controls.Add(language);AcceptButton=b;LayoutDirectionManager.Apply(this);left.Dock=AppSession.Persian?DockStyle.Right:DockStyle.Left;card.Left=AppSession.Persian?80:500;}
void AddField(Control p,string label,TextBox box,int y){var l=Theme.Label(label,9,FontStyle.Bold);l.Location=new Point(36,y);p.Controls.Add(l);box.Location=new Point(36,y+28);box.Size=new Size(348,30);box.Font=Theme.Font(11);box.BorderStyle=BorderStyle.FixedSingle;box.RightToLeft=AppSession.Persian?RightToLeft.Yes:RightToLeft.No;p.Controls.Add(box);}void DoLogin(){string role;if(data.Login(user.Text.Trim(),pass.Text,out role)){AppSession.UserName=user.Text.Trim();AppSession.Role=role;AppSession.CredentialStamp=new AuthenticationService().GetSessionStamp(AppSession.UserName);Hide();var m=new MainForm(data);m.FormClosed+=(s,e)=>Close();m.Show();}else error.Text=Localization.T("LoginError");}}
}
